cd /tmp/sv-775db7a0703c47609b6e9448e5968c30

# Extract dynamic symbols and use them to resolve addresses
# The addresses from the tombstone (PC offsets into libmonosgen-2.0.so):
ADDRS=(
  0x222098
  0x2241ac
  0x1abc80
  0x16de04
  0x2f4b20
  0x2f4c84
  0x2c1a40
)

# Use nm to get dynamic symbols sorted by address
nm -D --defined-only -n libmonosgen-2.0.so > /tmp/sv-775db7a0703c47609b6e9448e5968c30/dynsyms.txt
echo "Symbol count: $(wc -l < dynsyms.txt)"

# For each address, find the containing symbol
for addr in "${ADDRS[@]}"; do
  # Find the last symbol whose address is <= our target
  result=$(awk -v target="$addr" '
    BEGIN { target_dec = strtonum(target) }
    {
      sym_addr = strtonum("0x" $1)
      if (sym_addr <= target_dec) {
        last_addr = sym_addr
        last_name = $3
      } else {
        if (last_name != "") {
          offset = target_dec - last_addr
          printf "%s  =>  %s+0x%x\n", target, last_name, offset
        }
        exit
      }
    }
    END {
      if (last_name != "") {
        offset = target_dec - last_addr
        printf "%s  =>  %s+0x%x\n", target, last_name, offset
      }
    }
  ' dynsyms.txt)
  echo "$result"
done

