cd /tmp/sv-775db7a0703c47609b6e9448e5968c30

# Use readelf to find what section these addresses are in
readelf -S libmonosgen-2.0.so.dbg | grep -E '\.text|2f4'

echo "---"
# Try using the full symtab filtering out $d, $x, and thunk symbols
for addr_hex in 0x2f4b20 0x2f4c84; do
  addr_dec=$(printf '%d' $addr_hex)
  result=$(nm --defined-only -n libmonosgen-2.0.so.dbg 2>/dev/null | grep -v '^\s' | grep -vE '\$[dtx]|__CortexA53' | awk -v target="$addr_dec" '
    {
      sym_addr = strtonum("0x" $1)
      if (sym_addr <= target) {
        last_addr = sym_addr
        last_name = $3
        last_type = $2
      } else if (last_name != "") {
        offset = target - last_addr
        printf "%s+0x%x (%s)\n", last_name, offset, last_type
        found = 1
        exit
      }
    }
    END {
      if (!found && last_name != "") {
        offset = target - last_addr
        printf "%s+0x%x (%s)\n", last_name, offset, last_type
      }
    }
  ')
  echo "  $addr_hex  =>  $result"
done

