# Check section layout to understand where these addresses land
readelf -S libmonosgen-2.0.so | grep -E '\.(text|plt|got|data|bss|rodata)' | head -10

echo "---"
# Use the original (non-debug) binary with dynsym for these addresses
# Filter only FUNC type symbols from dynsym
readelf -W --dyn-syms libmonosgen-2.0.so | awk '$4 == "FUNC" && $7 != "UND"' | \
  awk '{printf "0x%s %s %s\n", $2, $3, $8}' | sort | \
  awk -v t1=$(printf '%d' 0x2f4b20) -v t2=$(printf '%d' 0x2f4c84) '
  {
    addr = strtonum($1)
    size = strtonum($2)
    name = $3
    if (addr <= t1 && addr + size > t1) print "0x2f4b20 => " name "+0x" sprintf("%x", t1 - addr)
    if (addr <= t2 && addr + size > t2) print "0x2f4c84 => " name "+0x" sprintf("%x", t2 - addr)
  }'", "description": "Use dynsym with size info"}

