  grep -vE '\$[dtx]|__CortexA53' | \
  awk -v t1=$(printf '%d' 0x2f4b20) -v t2=$(printf '%d' 0x2f4c84) '
  {
    addr = strtonum("0x" $1)
    if (addr <= t1) { l1_addr = addr; l1_name = $3; l1_type = $2 }
    if (addr <= t2) { l2_addr = addr; l2_name = $3; l2_type = $2 }
  }
  END {
    printf "0x2f4b20 => %s+0x%x (type: %s)\n", l1_name, t1 - l1_addr, l1_type
    printf "0x2f4c84 => %s+0x%x (type: %s)\n", l2_name, t2 - l2_addr, l2_type
  }'

echo "---"
